/** The TS fingerprint is byte-identical to canonical hooks/bus_log.py, on vectors generated by it. */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { busFingerprint, busSentLine, BUS_LOG_KEEP_SECONDS } from '../core/busLog';

const FIX = path.join(__dirname, '..', '..', 'src', 'test', 'fixtures', 'bus-fingerprints.json');
const { vectors } = JSON.parse(fs.readFileSync(FIX, 'utf8')) as { vectors: { text: string; fp: string }[] };

test('every vector from bus_log.py fingerprints identically — emoji cut, Python-only/JS-only whitespace, final sigma', () => {
  assert.ok(vectors.length >= 10);
  for (const v of vectors) assert.equal(busFingerprint(v.text), v.fp, `text ${JSON.stringify(v.text.slice(0, 30))}`);
});

test('the naive JS port would have been wrong on exactly these vectors (the fixture has teeth)', () => {
  const crypto = require('crypto') as typeof import('crypto');
  const naive = (t: string) => crypto.createHash('sha256').update(t.replace(/\s+/g, ' ').trim().toLowerCase().slice(0, 2000), 'utf8').digest('hex').slice(0, 24);
  const wrong = vectors.filter((v) => naive(v.text) !== v.fp).map((v) => v.text.slice(0, 12));
  assert.ok(wrong.length >= 3, `expected the emoji, \x1c/\x85 and BOM vectors to break a naive port; got ${JSON.stringify(wrong)}`);
});

test('a line is written once per window, never for empty text, and again after the window', () => {
  const now = 2_000_000_000;
  const first = busSentLine('Reply with the single word: pong', 'bg-test', 'send', 'app', '', now)!;
  const e = JSON.parse(first);
  assert.deepEqual(Object.keys(e), ['at', 'fp', 'to', 'action', 'via', 'head']);
  assert.equal(e.fp, '1ebbec6d50f6c1ef8512e212');
  assert.equal(busSentLine('reply   WITH the single word: pong', 'bg-test', 'send', 'app', first, now + 5), null, 'same fingerprint, already logged');
  assert.notEqual(busSentLine('Reply with the single word: pong', 'bg-test', 'send', 'app', first, now + BUS_LOG_KEEP_SECONDS + 1), null, 'past the window provenance.py trusts → log it again');
  assert.equal(busSentLine('   ', 'x', 'send', 'app', '', now), null);
});
